from pathlib import Path

companion = Path('app/components/audio-section-companion.tsx')
c = companion.read_text()
old = 'className={`audio-section-node ${isCurrent ? "is-current" : ""} ${isPast ? "is-past" : ""}`.trim()}'
new = 'className={`audio-section-node ${isCurrent ? "is-current" : ""} ${isPast ? "is-past" : ""} ${index <= 1 ? "is-edge-start" : ""} ${index >= markers.length - 2 ? "is-edge-end" : ""}`.trim()}'
if old in c:
    c = c.replace(old, new, 1)
companion.write_text(c)

css = Path('app/site.css')
s = css.read_text()
marker = '/* Audio Player visual verification pass 2 */'
if marker not in s:
    s += '''\n\n@layer site-components {\n  /* Audio Player visual verification pass 2 */\n  .audio-player-dock.is-expanded .audio-player-mini { grid-template-columns: minmax(0, 1fr) 30px; }\n  .audio-player-dock.is-expanded .audio-player-title { justify-self: stretch; max-width: none; width: 100%; }\n  .audio-player-dock.is-expanded .audio-player-title strong { max-width: none; width: 100%; }\n\n  .audio-player-volume input[type="range"] { appearance: none; background: transparent; height: 18px; margin: 0; padding: 0; }\n  .audio-player-volume input[type="range"]::-webkit-slider-runnable-track { background: color-mix(in srgb, var(--site-primary) 72%, var(--site-line)); border-radius: 1px; height: 2px; }\n  .audio-player-volume input[type="range"]::-moz-range-track { background: color-mix(in srgb, var(--site-primary) 72%, var(--site-line)); border-radius: 1px; height: 2px; }\n  .audio-player-volume input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none; background: var(--site-paper); border: 1.5px solid var(--site-primary); border-radius: 50%; height: 9px; margin-top: -3.5px; width: 9px; }\n  .audio-player-volume input[type="range"]::-moz-range-thumb { background: var(--site-paper); border: 1.5px solid var(--site-primary); border-radius: 50%; height: 9px; width: 9px; }\n\n  .audio-section-list button { min-height: 30px; padding: 4px 7px; }\n  .audio-section-list strong { font-size: 11px; line-height: 1.25; }\n  .audio-section-list time { font-size: 9px; }\n\n  .audio-section-node.is-edge-start .audio-section-node-tooltip { left: -8px; transform: translate(0, 5px); }\n  .audio-section-node.is-edge-start:hover .audio-section-node-tooltip,\n  .audio-section-node.is-edge-start:focus-visible .audio-section-node-tooltip { transform: translate(0, 0); }\n  .audio-section-node.is-edge-end .audio-section-node-tooltip { left: auto; right: -8px; transform: translate(0, 5px); }\n  .audio-section-node.is-edge-end:hover .audio-section-node-tooltip,\n  .audio-section-node.is-edge-end:focus-visible .audio-section-node-tooltip { transform: translate(0, 0); }\n  .audio-section-node-tooltip { max-width: 190px; min-width: 118px; padding: 6px 8px; }\n\n  @media (min-width: 701px) {\n    .audio-player-dock.is-expanded:has(.audio-section-toggle[aria-expanded="true"]) { min-height: 304px; }\n    .audio-player-dock.is-expanded:has(.audio-section-toggle[aria-expanded="true"]) .audio-player-details { min-height: 246px; }\n    .audio-player-dock.is-expanded:has(.audio-section-toggle[aria-expanded="true"]) .audio-player-controls { margin-top: auto; }\n    .audio-player-dock.is-expanded:has(.audio-section-toggle[aria-expanded="true"]) .audio-section-panel { max-height: 244px; }\n  }\n\n  @media (max-width: 700px) {\n    .audio-player-dock.is-expanded .audio-player-mini { grid-template-columns: minmax(0, 1fr) 30px; }\n    .audio-player-dock.is-expanded .audio-player-title { max-width: none; min-width: 0; width: 100%; }\n    .audio-player-dock.is-expanded .audio-player-title strong { -webkit-line-clamp: 2; font-size: 11px; max-width: none; width: 100%; }\n    .audio-player-fullscreen { display: none; }\n    .audio-player-utilities { grid-template-columns: minmax(0, 1fr) 30px; }\n    .audio-player-settings-panel { right: 0; }\n    .audio-section-list button { min-height: 34px; }\n  }\n}\n'''
css.write_text(s)
